pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 collectAmount, uint256 putAmount) public {
        // Keep amounts admissible and ensure unlockTime covers block.timestamp equality
        vm.assume(putAmount >= 1 ether);
        vm.assume(collectAmount <= putAmount);
        vm.assume(unlockTime >= 0 && unlockTime <= type(uint48).max);

        address actor = address(0x1234);
        vm.deal(actor, putAmount);

        // Warp to a future block so we can control unlockTime relative to it
        vm.warp(1000);
        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        uint256 balBefore = address(c).balance;

        // Perform Collect at the exact unlockTime block
        vm.warp(unlockTime);
        vm.prank(actor);
        try c.Collect(collectAmount) {
            // If call did not revert, balance should not have changed because block.timestamp == unlockTime is not strictly greater
            assertTrue(address(c).balance == balBefore);
        } catch {
            // Revert is also fine for reference; we only care about non-revert case
            assertTrue(true);
        }
    }
}

