pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit, uint256 amount) public {
        // restrict to admissible domain (deposit >= MinSum, amount <= deposit, both > 0)
        vm.assume(deposit >= 1 ether);
        vm.assume(amount <= deposit);
        vm.assume(amount > 0);

        // setup user
        address user = address(0x1234);
        vm.deal(user, deposit);

        // first Put with unlockTime = block.timestamp (0 means block.timestamp)
        vm.prank(user);
        c.Put{value: deposit}(block.timestamp);

        // warp to unlockTime so block.timestamp == unlockTime
        vm.warp(block.timestamp + 1);

        // record balance before Collect
        (uint unlockBefore, uint balanceBefore) = c.Acc(user);

        // attempt Collect when block.timestamp == unlockTime
        vm.prank(user);
        c.Collect(amount);

        // balance after
        (, uint balanceAfter) = c.Acc(user);

        // Reference invariant: balance unchanged when block.timestamp == unlockTime
        // The buggy version allows collection, thus reducing the balance.
        assertTrue(balanceAfter == balanceBefore);
    }
}

